import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';const headers={'cache-control':'private, no-store'};
const parse=value=>{try{const data=JSON.parse(value||'[]');return Array.isArray(data)?data:[]}catch{return[]}};
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const bundle=await ctx.env.DB.prepare("SELECT id,slug,title,cover_url,preview_urls,status,category,price,pages,created_at FROM products WHERE id=? AND source='bundle' AND deleted_at IS NULL").bind(ctx.params.id).first();if(!bundle)return json({error:'ไม่พบตะกร้ารวม'},404,headers);const members=(await ctx.env.DB.prepare(`SELECT p.id,p.slug,p.title,p.cover_url,p.preview_urls,b.sort_order FROM product_bundle_items b JOIN products p ON p.id=b.source_product_id WHERE b.bundle_product_id=? ORDER BY b.sort_order`).bind(bundle.id).all()).results||[],revisions=(await ctx.env.DB.prepare('SELECT id,old_cover_url,old_preview_urls,new_cover_url,new_preview_urls,created_at FROM bundle_preview_revisions WHERE bundle_product_id=? ORDER BY id DESC LIMIT 10').bind(bundle.id).all()).results||[];return json({bundle:{...bundle,preview_urls:parse(bundle.preview_urls)},members:members.map(item=>({...item,preview_urls:parse(item.preview_urls)})),revisions:revisions.map(item=>({...item,old_preview_urls:parse(item.old_preview_urls),new_preview_urls:parse(item.new_preview_urls)}))},200,headers)}
export async function onRequestPut(ctx){await ensureDatabase(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const bundle=await ctx.env.DB.prepare("SELECT id,cover_url,preview_urls FROM products WHERE id=? AND source='bundle' AND deleted_at IS NULL").bind(ctx.params.id).first();if(!bundle)return json({error:'ไม่พบตะกร้ารวม'},404,headers);const body=await ctx.request.json().catch(()=>null),urls=[...new Set((Array.isArray(body?.preview_urls)?body.preview_urls:[]).map(String))].slice(0,30);if(!urls.length)return json({error:'กรุณาเลือกรูปอย่างน้อย 1 รูป'},400,headers);const members=(await ctx.env.DB.prepare('SELECT p.cover_url,p.preview_urls FROM product_bundle_items b JOIN products p ON p.id=b.source_product_id WHERE b.bundle_product_id=?').bind(bundle.id).all()).results||[],allowed=new Set(members.flatMap(item=>[item.cover_url,...parse(item.preview_urls)]).filter(value=>typeof value==='string'&&(value.startsWith('/api/media/')||value.startsWith('/assets/'))));if(urls.some(url=>!allowed.has(url)))return json({error:'มีรูปที่ไม่ได้มาจากสมาชิกของชุดนี้'},400,headers);await ctx.env.DB.batch([ctx.env.DB.prepare('INSERT INTO bundle_preview_revisions(bundle_product_id,old_cover_url,old_preview_urls,new_cover_url,new_preview_urls,changed_by) VALUES(?,?,?,?,?,?)').bind(bundle.id,bundle.cover_url||'',bundle.preview_urls||'[]',urls[0],JSON.stringify(urls),auth.user.id),ctx.env.DB.prepare('UPDATE products SET cover_url=?,preview_urls=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(urls[0],JSON.stringify(urls),bundle.id)]);return json({ok:true,id:bundle.id,cover_url:urls[0],preview_urls:urls,preserved_fields:['id','slug','title','created_at','price','category','pages','bundle_members']},200,headers)}
